USE CC_DIVERGENCE, ONLY: CC_CHECK_DIVERGENCE, GET_VELOC_DIVERGENCE_CUTCELL, &
                         GET_FN_DIVERGENCE_CUTCELL, GET_CC_CELL_CONDUCTIVITY
USE COMPLEX_GEOMETRY
USE PRECISION_PARAMETERS
USE GLOBAL_CONSTANTS
USE MESH_VARIABLES
USE MESH_POINTERS
